'use strict';
let feedbackTab='new',feedbackError='',feedbackNotice='',feedbackBusy=false,feedbackCache=[],feedbackFetching=false,feedbackFetchedAt=0,journalRound='',journalHalf='front';
const feedbackStatus={new:'待查看',reading:'处理中',replied:'已回复',closed:'已处理'};
const feedbackCategories=['体验建议','功能异常','球场资料纠错','版权与合作'];
const communityKey='qingye.feedback.'+(new URLSearchParams(location.search).has('qa')?'qa':'v1');
function feedbackToken(){return Array.from(crypto.getRandomValues(new Uint8Array(32)),n=>n.toString(16).padStart(2,'0')).join('');}
function communityState(){try{return JSON.parse(localStorage.getItem(communityKey))||{draft:null,receipts:[]};}catch(e){return {draft:null,receipts:[]};}}
function communitySave(state){localStorage.setItem(communityKey,JSON.stringify(state));}
function feedbackDraft(){const state=communityState();if(!state.draft){state.draft={category:'体验建议',content:'',contact:'',receiptToken:feedbackToken()};communitySave(state);}return state.draft;}
async function feedbackApi(path,method='GET',body,token){const res=await fetch('/api/'+path,{method,cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{'X-Feedback-Token':token}:{})},body:body?JSON.stringify(body):undefined});let value;try{value=await res.json();}catch(e){throw Error('反馈服务暂未连接，草稿已保留，请稍后重试。');}if(!res.ok)throw Error(value.error||'提交未完成，草稿已保留。');return value;}
async function refreshFeedback(force=false){if(feedbackFetching||(!force&&Date.now()-feedbackFetchedAt<30000))return;const state=communityState();if(!state.receipts?.length)return;feedbackFetching=true;feedbackFetchedAt=Date.now();try{const items=await Promise.all(state.receipts.map(async r=>{try{return await feedbackApi('feedback/'+r.id,'GET',null,r.token);}catch(e){return {...r,unavailable:true};}}));feedbackCache=items;if(route.name==='feedback'||route.name==='profile')render();}finally{feedbackFetching=false;}}
const communityHome=home;home=function(){const html=communityHome(),anchor=section('最近的球场时光','history','全部记录');const support=action('community-about',`<span class="support-label">品牌支持</span><span class="support-copy">木圣 AI · 让技术服务热爱</span>${icon('chevron')}`,'quiet-support','aria-label="品牌支持：了解木圣AI与青野"');return html.replace(anchor,support+anchor);};
const communityProfile=profilePage;profilePage=function(){const count=feedbackCache.filter(f=>f.reply&&f.updated>(communityState().seenReplyAt||0)).length;return communityProfile().replace(/(<button[^>]*data-action="about"[^>]*>)/,go('feedback',icon('info')+'<span class="grow">信息与问题反馈</span><span class="end-text">'+(count?count+' 条回复':'建议 · 纠错')+'</span>'+icon('chevron'),'menu-row')+'$1');};
function aboutPage(){return `<section class="about-intro"><img src="assets/logo.svg" alt="青野标志"><p class="eyebrow">QINGYE GOLF</p><h1>把注意力，留给下一杆。</h1><p>一个因为热爱而生的高尔夫记分工具。</p></section><section class="card about-story"><h2>青野，起于一点不甘心</h2><p>我们喜欢高尔夫，也在意一张记分卡带来的感受。用过一些工具后，总觉得：记一杆，不该绕很多弯；打一场球，也不该被太多信息打断。</p><p>所以，我们想自己做一个。让页面清爽一点，让操作顺手一点，把时间还给同组的交流、沿途的风景，还有下一次挥杆。</p></section><section class="card about-story"><h2>做企业的 AI，也做自己的热爱</h2><p>青野由<strong>上海木圣网络科技有限公司</strong>发起。我们的日常，是把 AI 应用到企业中，帮助团队提升效率、梳理流程，让技术真正解决实际问题。</p><p>青野是这份工作之外的一点情怀：不以盈利为出发点，只想为高尔夫爱好者做一款简洁、好看、用起来舒服的记分小程序。</p><p>我们希望记分过程保持安静。首页只保留一条克制的品牌支持入口，不用弹窗广告打断一场好球。</p></section><section class="card about-story"><h2>这一次，让 AI 从想法做到程序</h2><p>青野的产品方案、界面设计和程序开发，全部由 AI 辅助完成。人负责提出需求、反复体验、确认每一次取舍；AI 把想法一步步变成可以使用的作品。</p><p>它不意味着没有瑕疵，却让我们更相信：一个普通爱好者心里的“能不能更好一点”，也值得被认真实现。</p></section><section class="card about-story"><h2>一起把青野，做得更好</h2><p>球场资料可能有遗漏，图源与版本也需要持续核实。如果你发现错误、遇到不好用的地方，或有更好的建议，欢迎告诉我们。</p><p>如果图片、文字或其他资料涉及版权，请及时联系。我们会认真核实、积极沟通，妥善处理。</p>${go('feedback','留下你的反馈 '+icon('arrow'),'btn secondary full')}</section><section class="card about-contact"><h2>联系青野</h2><p>上海木圣网络科技有限公司</p><a class="contact-phone" href="tel:18521597226">${icon('user')}<span><strong>吴先生</strong><small>185 2159 7226</small></span>${icon('chevron')}</a><p class="tiny">企业 AI 应用 · 效率提升 · 业务流程优化</p></section><p class="about-signoff">愿青野陪你安静记分，自在挥杆。</p>`;}
function feedbackPage(){const state=communityState(),draft=feedbackDraft(),records=feedbackCache.length?feedbackCache:state.receipts||[];return `${title('把不好用的地方，告诉我们','你的建议、纠错和版权沟通，我们都会认真对待。')}<div class="segment feedback-tabs">${action('feedback-tab','提交反馈',feedbackTab==='new'?'active':'','data-value="new"')}${action('feedback-tab','我的反馈'+(records.length?' · '+records.length:''),feedbackTab==='history'?'active':'','data-value="history"')}</div>${feedbackNotice?`<div class="notice feedback-success" role="status">${icon('check')}<span>${esc(feedbackNotice)}</span></div>`:''}${feedbackTab==='new'?`<form data-community-form="feedback"><section class="card"><label class="v3-field"><span>反馈类型</span><select name="category" id="feedback-category">${feedbackCategories.map(t=>`<option ${draft.category===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="v3-field"><span>问题或建议 <small>必填</small></span><textarea name="content" id="feedback-content" minlength="5" maxlength="2000" required rows="6" placeholder="例如：在哪个页面，做了什么操作，遇到了什么问题？也欢迎告诉我们你希望增加的功能。">${esc(draft.content)}</textarea></label><label class="v3-field"><span>联系方式 <small>选填，仅用于回复本次反馈</small></span><input name="contact" id="feedback-contact" maxlength="120" value="${esc(draft.contact)}" placeholder="手机号、微信号或邮箱"></label><p class="tiny">草稿会保留在此浏览器。提交后可在“我的反馈”查看处理进度和回复。</p></section><p class="feedback-error" role="alert">${esc(feedbackError)}</p><button type="submit" class="btn primary full" ${feedbackBusy?'disabled':''}>${feedbackBusy?'正在提交…':'提交反馈'}</button><p class="tiny feedback-privacy">仅提交你填写的内容，不附带球局、位置或通讯录。当前 H5 连接本机反馈后台，正式小程序上线时会接入对应服务。</p></form>`:`<div class="feedback-history-head"><p class="tiny">反馈回执保存在当前浏览器。</p>${action('feedback-refresh','刷新状态','text-link')}</div>${records.length?records.map(f=>`<article class="card feedback-record"><div class="row"><span class="tag ${f.status==='replied'?'green':'gray'}">${f.unavailable?'暂未连接':feedbackStatus[f.status]||'已提交'}</span><small>${new Date(f.created*1000).toLocaleDateString('zh-CN')}</small></div><h3>${esc(f.category||'用户反馈')}</h3><p class="feedback-content">${esc(f.content||'已提交，连接后台后可查看详情。')}</p><small>回执 ${esc(f.id)}</small>${f.reply?`<div class="feedback-reply"><b>青野回复</b><p>${esc(f.reply)}</p></div>`:''}</article>`).join(''):`<div class="card feedback-empty"><h3>这里会留下我们的交流</h3><p>你还没有提交反馈，想法和建议都欢迎。</p>${action('feedback-tab','写下第一条反馈','btn secondary','data-value="new"')}</div>`}`}`;}
const communityScore=scorePage;scorePage=function(){const r=round();let html=communityScore();if(!r)return html;html=html.replace(/(<button[^>]*class="score-map-button"[^>]*>)[\s\S]*?<\/button>/,`$1${icon('flag')} 球场指南</button>`);return html.replace(/<button[^>]*data-path="distance\/[^>]*>[\s\S]*?<\/button>/g,'');};
cardPage=function(){const r=round();if(!r)return empty('未找到球局','','history');if(journalRound!==r.id){journalRound=r.id;journalHalf=r.currentHole>9?'back':'front';}const half=journalHalf==='back'&&r.holes.length>9?'back':'front',hs=r.holes.filter(h=>half==='front'?h.number<=9:h.number>9),roundPar=r.holes.reduce((n,h)=>n+h.par,0),scope=r.ruleSnapshot.scoring.type==='match_play'?'main':undefined;return `${title('完整记分卡',r.courseName)}<div class="journal-summary"><div><small>本轮标准杆</small><b>${roundPar}</b></div><div><small>球洞</small><b>${r.holes.length}</b></div><div><small>同组球友</small><b>${r.players.length}</b></div></div><div class="segment journal-half">${action('journal-half','前九洞',half==='front'?'active':'','data-value="front"')}${r.holes.length>9?action('journal-half','后九洞',half==='back'?'active':'','data-value="back"'):''}</div><p class="tiny">按球友分组查看，点开洞卡可以记分或更正。</p><div class="journal-players">${r.players.map((p,i)=>{const sum=GolfScoreTotals.summary(r,p.id);const played=hs.filter(h=>r.scores[p.id]?.[h.number]?.completion==='holed_out');const halfStrokes=played.reduce((n,h)=>n+r.scores[p.id][h.number].grossStrokes,0);return `<details class="journal-player card" ${p.id===(r.currentPlayer||r.players[0].id)?'open':''}><summary><span class="journal-person">${av(p,i)}<span><b>${esc(p.id==='me'?'我':p.name)}</b><small>已完 ${sum.played}/${r.holes.length} 洞 · ${esc(p.tee)}</small></span></span><span class="journal-total"><b>${sum.liveTotal}<small>总杆</small></b><span>${sum.diff===0?'E':sum.diff>0?'+'+sum.diff:sum.diff}</span></span>${icon('chevron')}</summary><div class="journal-half-summary"><b>${half==='front'?'前九':'后九'}实际 ${played.length?halfStrokes:'—'} 杆</b><span>已完 ${played.length}/${hs.length} 洞</span></div><div class="journal-holes">${hs.map(h=>{const s=r.scores[p.id]?.[h.number],a=s?scoreAppearance(s.grossStrokes,h.par,s.completion):null,value=!s?'—':s.completion==='holed_out'?s.grossStrokes:completionNames[s.completion]||'特殊';const label=!s?'待记录':s.completion!=='holed_out'?'特殊状态':a?.label||a?.delta||'';return action('cell',`<span class="journal-hole-title"><b>${h.number}<small>洞</small></b><span>Par ${h.par}</span></span><span class="journal-hole-score"><span class="score-mark ${a?.kind||'blank'}">${esc(value)}</span><small>${esc(label)}</small></span>`,`journal-hole ${!s?'unrecorded':''}`,`data-rid="${esc(r.id)}" data-id="${esc(p.id)}" data-hole="${h.number}" aria-label="${esc(p.name)}第${h.number}洞，标准杆${h.par}，${s?String(value)+'杆':'未记录'}"`);}).join('')}</div></details>`;}).join('')}</div><p class="tiny journal-total-note">总杆按本轮标准杆加当前杆差显示；未记录的球洞仍保留空白。半场实际杆只合计已实际完洞成绩。</p>${r.ruleSnapshot.scoring.type!=='record_only'||r.ruleSnapshot.handicap.mode!=='none'?`<details class="card journal-calculations"><summary>让杆与比赛计算明细 <small>选看</small></summary><p class="tiny">计算值独立于实际杆数。</p>${r.players.map(p=>`<h3>${esc(p.name)}</h3><div class="table-scroll"><table class="data-table"><tr><th>洞</th><th>实际</th><th>让杆</th><th>净杆</th><th>计分</th></tr>${hs.map(h=>{const d=R.derivePlayerHole(r,p.id,h.number,undefined,scope);return `<tr><td>${h.number}</td><td>${d.gross??'—'}</td><td>${d.allowance}</td><td>${d.net??'—'}</td><td>${d.value??'—'}</td></tr>`;}).join('')}</table></div>`).join('')}</details>`:''}<div class="round-actions">${action('v3-show-rules','本场规则','btn outline')}${go((R.isFinished(r)&&!edit?'result/':'score/')+r.id,'返回本轮','btn primary')}</div>`;};
const communityActions=handleAction;handleAction=async function(el,event){const a=el.dataset.action;
 if(a==='about'||a==='community-about'){nav('about');return;}
 if(a==='feedback-tab'){feedbackTab=el.dataset.value;if(feedbackTab==='history'){const state=communityState();state.seenReplyAt=Math.floor(Date.now()/1000);communitySave(state);}feedbackError='';render();if(feedbackTab==='history')refreshFeedback(true);return;}
 if(a==='feedback-refresh'){feedbackFetchedAt=0;await refreshFeedback(true);toast('反馈状态已更新');return;}
 if(a==='journal-half'){journalHalf=el.dataset.value;render();return;}
 return communityActions(el,event);
};
function saveFeedbackDraft(){const f=document.querySelector('[data-community-form="feedback"]');if(!f)return;const state=communityState(),fd=new FormData(f);state.draft={...(state.draft||feedbackDraft()),category:fd.get('category'),content:fd.get('content'),contact:fd.get('contact')};communitySave(state);}
document.addEventListener('input',e=>{if(e.target.closest('[data-community-form="feedback"]'))saveFeedbackDraft();});
document.addEventListener('change',e=>{if(e.target.closest('[data-community-form="feedback"]'))saveFeedbackDraft();});
document.addEventListener('submit',async e=>{const f=e.target;if(f.dataset.communityForm!=='feedback')return;e.preventDefault();if(feedbackBusy)return;saveFeedbackDraft();const draft=feedbackDraft();feedbackBusy=true;feedbackError='';feedbackNotice='';const button=f.querySelector('[type=submit]');button.disabled=true;button.textContent='正在提交…';try{const value=await feedbackApi('feedback','POST',draft),state=communityState();if(!state.receipts.some(r=>r.id===value.id))state.receipts.unshift({id:value.id,token:draft.receiptToken,category:draft.category,content:draft.content,status:'new',created:Math.floor(Date.now()/1000)});state.draft=null;communitySave(state);feedbackCache=[];feedbackTab='history';feedbackNotice='已保存到反馈后台。你可以在这里查看后续处理和回复。';feedbackFetchedAt=0;}catch(error){feedbackError=error.message;}finally{feedbackBusy=false;render();if(feedbackTab==='history')refreshFeedback(true);}});
const communityRender=render;render=function(){communityRender();if(['profile','feedback'].includes(route.name))refreshFeedback();};
render();
